const clean=(v,n=2000)=>String(v||'').trim().slice(0,n);const allowed=req=>{const o=req.headers.origin;return !o||/^https:\/\/(www\.)?kathyaai\.com$/i.test(o)};
export default async function handler(req,res){if(req.method!=='POST')return res.status(405).json({error:'Method not allowed'});if(!allowed(req))return res.status(403).json({error:'Forbidden'});if(!process.env.WHATSAPP_ACCESS_TOKEN||!process.env.WHATSAPP_PHONE_NUMBER_ID)return res.status(503).json({error:'WhatsApp is not configured'});const to=clean(req.body?.to,30).replace(/[^0-9]/g,''),body=clean(req.body?.message,1500);if(!/^\d{8,15}$/.test(to)||!body)return res.status(400).json({error:'Invalid recipient or message'});try{const r=await fetch('https://graph.facebook.com/v23.0/'+encodeURIComponent(process.env.WHATSAPP_PHONE_NUMBER_ID)+'/messages',{method:'POST',headers:{Authorization:'Bearer '+process.env.WHATSAPP_ACCESS_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({messaging_product:'whatsapp',to,type:'text',text:{body}})});const data=await r.json();if(!r.ok){console.error('WhatsApp send failed',r.status);return res.status(502).json({error:'Message provider rejected the request'});}return res.status(200).json({ok:true,id:data.messages?.[0]?.id||null});}catch(e){console.error('WhatsApp send error');return res.status(502).json({error:'Message service unavailable'});}}